"""Algorithm B - Generic Symmetric Reduction and the Universal Invariant Polynomial.

For F in Z[X] and a modulus N, computes the polynomial psi(s) = Psi_F(s, N) with
the property Psi_F(p+q, pq) = F(p) F(q) for ALL integers p, q. The reduction is
carried out generically over Z[N][s], so nothing about the hidden factors is
used. Complexity: O(d^2) coefficient operations for d = deg F; deg psi <= 2d.
"""

from __future__ import annotations

from typing import List, Sequence

Poly = List[int]  # coefficients in s, lowest degree first


def _trim(a: Poly) -> Poly:
    b = list(a)
    while b and b[-1] == 0:
        b.pop()
    return b


def padd(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim([(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
                  for i in range(n)])


def psub(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim([(a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0)
                  for i in range(n)])


def pmul(a: Poly, b: Poly) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                out[i + j] += x * y
    return _trim(out)


def pscale(a: Poly, c: int) -> Poly:
    return _trim([c * x for x in a])


def peval(a: Poly, x: int) -> int:
    acc = 0
    for c in reversed(a):
        acc = acc * x + c
    return acc


def universal_invariant_polynomial(F: Sequence[int], N: int) -> Poly:
    """psi(s) = A_F^2 + A_F B_F s + B_F^2 N, where X^k = B_k X + A_k mod X^2-sX+N.

    Recursion: A_0 = 1, B_0 = 0, A_{k+1} = -N B_k, B_{k+1} = B_k s + A_k.
    """
    A: Poly = [1]
    B: Poly = []
    AF: Poly = []
    BF: Poly = []
    for c in F:
        if c:
            AF = padd(AF, pscale(A, c))
            BF = padd(BF, pscale(B, c))
        A, B = pscale(B, -N), padd(pmul(B, [0, 1]), A)
    return padd(padd(pmul(AF, AF), pmul(pmul(AF, BF), [0, 1])),
                pscale(pmul(BF, BF), N))


def degree(a: Poly) -> int:
    return len(_trim(a)) - 1


if __name__ == "__main__":
    examples = [("X", [0, 1]), ("X+1", [1, 1]), ("X^2", [0, 0, 1]),
                ("X^2+1", [1, 0, 1]), ("2X^3-X+5", [5, -1, 0, 2])]
    N, p, q = 15, 3, 5
    for name, F in examples:
        psi = universal_invariant_polynomial(F, N)
        lhs = peval(psi, p + q)
        rhs = peval(list(F), p) * peval(list(F), q)
        print(f"F = {name:10s}  psi = {psi}  deg {degree(psi)}  "
              f"psi(p+q) = {lhs}  F(p)F(q) = {rhs}  match {lhs == rhs}")

"""Algorithm C - Dichotomy Decision and Closed-Form Factor Recovery.

Given a polynomial invariant F, a modulus N and the observed value
T = F(p)F(q), decide which side of the multiplicative dichotomy the invariant
falls on, and on the informative side return every candidate factorization.

If the specialized universal polynomial psi = Psi_F(., N) is constant the
invariant is N-only: it takes the same value on every factorization of N.
Otherwise the hidden sum s = p+q is an integer root of psi - T, a nonzero
polynomial of degree at most 2 deg F, so at most 2 deg F candidates arise; each
candidate s with s^2 - 4N a perfect square yields the pair
((s - sqrt(s^2-4N))/2, (s + sqrt(s^2-4N))/2).

Complexity: O(d^2) to build psi, plus integer root finding on a degree-<= 2d
polynomial (rational root theorem, or a bounded scan since 0 < s <= N+1).
"""

from __future__ import annotations

from math import isqrt
from typing import Dict, List, Sequence, Tuple

Poly = List[int]


def _trim(a: Poly) -> Poly:
    b = list(a)
    while b and b[-1] == 0:
        b.pop()
    return b


def padd(a: Poly, b: Poly) -> Poly:
    n = max(len(a), len(b))
    return _trim([(a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
                  for i in range(n)])


def pmul(a: Poly, b: Poly) -> Poly:
    if not a or not b:
        return []
    out = [0] * (len(a) + len(b) - 1)
    for i, x in enumerate(a):
        if x:
            for j, y in enumerate(b):
                out[i + j] += x * y
    return _trim(out)


def pscale(a: Poly, c: int) -> Poly:
    return _trim([c * x for x in a])


def peval(a: Poly, x: int) -> int:
    acc = 0
    for c in reversed(a):
        acc = acc * x + c
    return acc


def universal_invariant_polynomial(F: Sequence[int], N: int) -> Poly:
    A: Poly = [1]
    B: Poly = []
    AF: Poly = []
    BF: Poly = []
    for c in F:
        if c:
            AF = padd(AF, pscale(A, c))
            BF = padd(BF, pscale(B, c))
        A, B = pscale(B, -N), padd(pmul(B, [0, 1]), A)
    return padd(padd(pmul(AF, AF), pmul(pmul(AF, BF), [0, 1])),
                pscale(pmul(BF, BF), N))


def divisors(n: int) -> List[int]:
    out: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            if d != n // d:
                out.append(n // d)
        d += 1
    return sorted(out)


def integer_roots(poly: Poly) -> List[int]:
    """Integer roots via the rational root theorem (poly assumed nonzero)."""
    poly = _trim(poly)
    if not poly:
        raise ValueError("zero polynomial has infinitely many roots")
    shift = 0
    while poly[0] == 0:            # factor out powers of s
        poly = poly[1:]
        shift = 1
    roots: List[int] = [0] if shift else []
    const = abs(poly[0])
    for d in divisors(const):
        for s in (d, -d):
            if peval(poly, s) == 0:
                roots.append(s)
    return sorted(set(roots))


def recover_from_sum(N: int, s: int) -> Tuple[int, int]:
    disc = s * s - 4 * N
    r = isqrt(disc)
    return ((s - r) // 2, (s + r) // 2)


def dichotomy_decide(F: Sequence[int], N: int, T: int) -> Dict[str, object]:
    """Classify the invariant and, if informative, return candidate factorizations."""
    psi = universal_invariant_polynomial(F, N)
    deg = len(_trim(psi)) - 1
    if deg <= 0:
        return {"side": "N-only",
                "value_on_every_factorization": psi[0] if psi else 0,
                "candidates": []}
    residual = padd(psi, [-T])
    cands: List[Tuple[int, int]] = []
    for s in integer_roots(residual):
        disc = s * s - 4 * N
        if disc >= 0 and isqrt(disc) ** 2 == disc:
            p, q = recover_from_sum(N, s)
            if p * q == N:
                cands.append((p, q))
    return {"side": "circular (sum-revealing)",
            "degree": deg,
            "max_candidates": 2 * (len(list(F)) - 1),
            "candidates": cands}


if __name__ == "__main__":
    N, p, q = 3233, 53, 61            # a small RSA-style modulus
    for name, F in [("X", [0, 1]), ("X+1", [1, 1]), ("X^2", [0, 0, 1]),
                    ("X^2+1", [1, 0, 1])]:
        T = peval(list(F), p) * peval(list(F), q)
        print(f"F = {name:6s}  T = {T:12d}  ->  {dichotomy_decide(F, N, T)}")

"""Algorithm D - Polynomial Success Counting against the Certified Barrier.

For a fixed polynomial P in Q[X] and a bound X, enumerate exactly the semiprimes
N = pq <= X on which P returns the correct smaller factor, and compare the count
with the certified bound deg(P) * pi(sqrt X) of the counting barrier.

Mathematical basis: for a fixed small factor p, every success gives a root of the
nonzero polynomial P - p, so there are at most deg P of them; and p <= sqrt X
whenever pq <= X with p < q. Complexity: O(sqrt X log log X) for the sieve plus
O(pi(sqrt X) * d^2) for the root enumeration.
"""

from __future__ import annotations

from fractions import Fraction
from math import isqrt
from typing import Dict, List, Sequence, Tuple

RatPoly = List[Fraction]  # lowest degree first


def peval(a: Sequence[Fraction], x: Fraction) -> Fraction:
    acc = Fraction(0)
    for c in reversed(list(a)):
        acc = acc * x + c
    return acc


def sieve_primes(limit: int) -> List[int]:
    if limit < 2:
        return []
    ok = [True] * (limit + 1)
    ok[0] = ok[1] = False
    for i in range(2, isqrt(limit) + 1):
        if ok[i]:
            for j in range(i * i, limit + 1, i):
                ok[j] = False
    return [i for i, f in enumerate(ok) if f]


def rational_roots(poly: Sequence[Fraction]) -> List[Fraction]:
    """All rational roots, by clearing denominators and applying the rational
    root theorem."""
    coeffs = list(poly)
    while coeffs and coeffs[-1] == 0:
        coeffs.pop()
    if not coeffs:
        raise ValueError("zero polynomial")
    den = 1
    for c in coeffs:
        den = den * c.denominator // _gcd(den, c.denominator)
    ints = [int(c * den) for c in coeffs]
    shift = 0
    while ints and ints[0] == 0:
        ints = ints[1:]
        shift = 1
    roots: List[Fraction] = [Fraction(0)] if shift else []
    if not ints:
        return roots
    a0, an = abs(ints[0]), abs(ints[-1])
    for num in _divisors(a0):
        for de in _divisors(an):
            for sign in (1, -1):
                r = Fraction(sign * num, de)
                if peval([Fraction(c) for c in ints], r) == 0:
                    roots.append(r)
    return sorted(set(roots))


def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def _divisors(n: int) -> List[int]:
    if n == 0:
        return [1]
    out: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            out.append(d)
            out.append(n // d)
        d += 1
    return sorted(set(out))


def count_polynomial_successes(P: Sequence[Fraction], X: int) -> Dict[str, object]:
    """Exact success set of P below X, with the certified counting-barrier bound."""
    deg = len(list(P)) - 1
    small = sieve_primes(isqrt(X))
    prime_set = set(sieve_primes(X // 2 + 1))
    successes: List[Tuple[int, int]] = []
    for p in small:
        shifted = [c - (Fraction(p) if i == 0 else Fraction(0))
                   for i, c in enumerate(P)]
        try:
            rts = rational_roots(shifted)
        except ValueError:
            continue                     # P is identically p: excluded by hypothesis
        for r in rts:
            if r.denominator != 1:
                continue
            n = int(r)
            if n <= 0 or n > X or n % p:
                continue
            q = n // p
            if q > p and q in prime_set:
                successes.append((p, q))
    return {"successes": sorted(set(successes)),
            "count": len(set(successes)),
            "certified_bound": deg * len(small),
            "pi_sqrt_X": len(small),
            "degree": deg}


if __name__ == "__main__":
    # P(N) = (N + 6) / 8 succeeds exactly where 8p - 6 = N = pq.
    P = [Fraction(6, 8), Fraction(1, 8)]
    print(count_polynomial_successes(P, 20000))
